            }
        } 
        // Fill in the comparison window
        byte[] buffer = new byte[length + (offsetRangeEnd - offsetRangeBegin)];
        int n = tis.read(buffer);
        if (n > 0) {
            offset += n;
        }
        while ((n != (-1)) && (offset < (offsetRangeEnd + length))) {
