public String detect(InputStream stream, Metadata metadata) throws IOException {
    if (stream == null) {
        return // PATH: Test should invoke the next ProbabilisticMimeDetectionSelector.detect(...) [step in execution path]
        detector.detect(null, metadata, new ParseContext()).toString();
